example.code:
var adapter = new CompoundAdapter(logger, context);

// Add a valid compound
var result = adapter.AddCompound("Methane");
if (result.Success)
{
    Console.WriteLine("Methane added successfully");
}

// Attempt to add an invalid compound
var result2 = adapter.AddCompound("InvalidCompound");
if (!result2.Success)
{
    Console.WriteLine($"Error: {result2.Message}");
}

var adapter = new CompoundAdapter(logger, context);
adapter.AddCompound("Methane");
adapter.AddCompound("Ethane");

var result = adapter.GetCompounds();
if (result.Success)
{
    foreach (var compound in result.Data)
    {
        Console.WriteLine($"Compound: {compound}");
    }
}

var adapter = new CompoundAdapter(logger, context);
var available = adapter.GetAvailableCompounds();

Console.WriteLine($"Total available compounds: {available.Count}");
foreach (var compound in available)
{
    Console.WriteLine($"  - {compound}");
}

var adapter = new PropertyPackageAdapter(logger, context);

// Set Peng-Robinson property package
var result = adapter.SetPropertyPackage("Peng-Robinson");
if (result.Success)
{
    Console.WriteLine("Property package set successfully");
}

// Try using an alias
var result2 = adapter.SetPropertyPackage("PR");  // Same as "Peng-Robinson"

// Invalid package name
var result3 = adapter.SetPropertyPackage("InvalidPackage");
if (!result3.Success)
{
    Console.WriteLine($"Error: {result3.Message}");
}

var adapter = new PropertyPackageAdapter(logger, context);
adapter.SetPropertyPackage("PR");

var result = adapter.GetPropertyPackageName();
if (result.Success)
{
    Console.WriteLine($"Current package: {result.Data}");  // Output: "Peng-Robinson"
}

var adapter = new PropertyPackageAdapter(logger, context);
var result = adapter.GetAvailablePackages();

if (result.Success)
{
    Console.WriteLine("Available property packages:");
    foreach (var package in result.Data)
    {
        Console.WriteLine($"  - {package}");
    }
}

var adapter = new StreamAdapter(logger, context);

var composition = new Composition(new[] { 0.7, 0.2, 0.1 });  // 3 compounds
var properties = new StreamProperties(
    temperatureK: 298.15,
    pressurePa: 101325,
    molarFlowMolPerSec: 100.0,
    composition: composition);

// Create feed stream (isSource=true)
var feedResult = adapter.CreateStream("Feed", properties, isSource: true);

// Create outlet stream (isSource=false, default)
var outletResult = adapter.CreateStream("Outlet", properties);

var adapter = new StreamAdapter(logger, context);

// Set temperature
var result = adapter.SetProperty("S1", "temperature", 320.0);

// Set pressure using CAPE-OPEN name
var result2 = adapter.SetProperty("S1", "pressure", 200000.0);

var adapter = new StreamAdapter(logger, context);

var result = adapter.GetProperty("S1", "temperature");
if (result.Success)
{
    double temp = (double)result.Data;
    Console.WriteLine($"Temperature: {temp} K");
}

var adapter = new UnitOpAdapter(logger, context);

// Set pressure drop
var result = adapter.SetParameter("U1", "PressureDrop", 5000.0);
if (result.Success)
{
    Console.WriteLine("Pressure drop set to 5000 Pa");
}

var adapter = new UnitOpAdapter(logger, context);

var result = adapter.GetParameter("U1", "PressureDrop");
if (result.Success)
{
    double pressureDrop = (double)result.Data;
    Console.WriteLine($"Pressure drop: {pressureDrop} Pa");
}

var adapter = new UnitOpAdapter(logger, context);

var result = adapter.GetPorts("U1");
if (result.Success)
{
    var ports = (Dictionary<string, string>)result.Data;
    foreach (var port in ports)
    {
        Console.WriteLine($"Port: {port.Key}, Type: {port.Value}");
    }
}

var adapter = new ConnectionAdapter(logger, context);

// Connect feed stream to separator inlet
var result = adapter.ConnectStream("S1", "U1", "Inlet");
if (result.Success)
{
    Console.WriteLine($"Stream connected: {result.ConnectionInfo}");
}

var adapter = new ConnectionAdapter(logger, context);

var result = adapter.DisconnectStream("S1");
if (result.Success)
{
    Console.WriteLine("Stream disconnected successfully");
}

var adapter = new ConnectionAdapter(logger, context);

var result = adapter.GetConnection("S1");
if (result.Success)
{
    var conn = result.ConnectionInfo;
    Console.WriteLine($"Stream {conn.StreamId} connected to {conn.UnitId}.{conn.PortName}");
}

var adapter = new ConnectionAdapter(logger, context);

var result = adapter.GetAllConnections();
if (result.Success)
{
    var connections = (List<ConnectionInfo>)result.Data;
    Console.WriteLine($"Total connections: {connections.Count}");
    foreach (var conn in connections)
    {
        Console.WriteLine($"  {conn}");
    }
}

var adapter = new ConnectionAdapter(logger, context);

var result = adapter.ValidateTopology();
if (!result.Success)
{
    Console.WriteLine($"Topology validation failed: {result.Message}");
}

