    Console.WriteLine($"Supported: {property}");
}

var capeOpenProperties = CapeOpenPropertyConverter.GetSupportedCapeOpenNames();
foreach (var property in capeOpenProperties)
{
    Console.WriteLine($"CAPE-OPEN: {property}");
}

